import java.util.*;
import java.math.*;

public class Main {
    public static void main(String[] args) {
        Scanner sc = new Scanner(System.in);
        int n = sc.nextInt();
        int k = sc.nextInt();
        int mod = sc.nextInt();

        // Function for modular exponentiation
        long pow_mod(long base, long exp, int mod) {
            long res = 1;
            while (exp > 0) {
                if ((exp & 1) == 1) res = (res * base) % mod;
                base = (base * base) % mod;
                exp >>= 1;
            }
            return res;
        }

        if (n % 2 == 1) {
            System.out.println(pow_mod(k, n, mod));
        } else {
            long[] factorial = new long[n + 1];
            long[] inv_factorial = new long[n + 1];
            factorial[0] = 1;
            for (int i = 1; i <= n; i++) {
                factorial[i] = (factorial[i - 1] * i) % mod;
            }
            inv_factorial[n] = pow_mod(factorial[n], mod - 2, mod);
            for (int i = n - 1; i >= 0; i--) {
                inv_factorial[i] = (inv_factorial[i + 1] * (i + 1)) % mod;
            }

            List<Integer> positions = new ArrayList<>();
            for (int i = 0; i < n; i++) {
                if ((n & (1 << i)) != 0) {
                    positions.add(i);
                }
            }

            int[] segment_lengths = new int[n + 1];
            for (int i = 0; i <= n; i++) {
                int j = i;
                while (j != 0) {
                    segment_lengths[i]++;
                    j = (j - 1) & j;
                }
            }

            boolean[] visited_mask = new boolean[1 << n];
            for (int mask = (1 << n) - 1; mask >= 0; mask--) {
                if (mask == 0) break;
                visited_mask[mask] = true;
            }

            long[][] dp = new long[n + 1][1 << n];
            dp[0][0] = 1;

            for (int mask = 0; mask < (1 << n); mask++) {
                for (int s = 0; s <= n; s++) {
                    if (dp[s][mask] == 0) continue;
                    int remaining = mask ^ ((1 << n) - 1);
                    for (int sub_mask = remaining; sub_mask > 0; sub_mask = (sub_mask - 1) & remaining) {
                        int len = Math.min(k, segment_lengths[mask ^ sub_mask] + 1);
                        for (int s2 = 1; s2 <= len; s2++) {
                            if (dp[s - 1][mask ^ sub_mask] != 0) {
                                long val = dp[s - 1][mask ^ sub_mask] * inv_factorial[sub_mask] % mod;
                                dp[s][mask] = (dp[s][mask] + val) % mod;
                            }
                        }
                    }
                }
            }

            long total = 0;
            int full_mask = (1 << n) - 1;
            int max_i = Math.min(k, segment_lengths[n]);
            for (int i = 0; i <= max_i; i++) {
                if (dp[i][full_mask] != 0) {
                    long val = dp[i][full_mask] * factorial[k] % mod;
                    val = val * inv_factorial[k - i] % mod;
                    val = val * inv_factorial[i] % mod;
                    val = val * factorial[n] % mod;
                    total = (total + val) % mod;
                }
            }
            System.out.println((pow_mod(k, n, mod) - total + mod) % mod);
        }
        sc.close();
    }
}

